:root {
  color-scheme: light;
  font-family: system-ui, sans-serif;
  font-size: 16px;
  color: #202b3c;
  background: #e9f2ed;
  --ink: #202b3c;
  --muted: #637267;
  --paper: #fffdf5;
  --green: #286650;
  --yellow: #f2cc59;
}

* { box-sizing: border-box; }
body {
  min-height: 100vh;
  margin: 0;
  padding: 24px;
  display: grid;
  place-items: center;
  background-color: #e9f2ed;
  background-image: radial-gradient(#b7d1c2 1.5px, transparent 1.5px);
  background-size: 22px 22px;
}
.card {
  width: min(100%, 560px);
  padding: clamp(24px, 6vw, 44px);
  border: 3px solid var(--ink);
  border-radius: 18px;
  background: var(--paper);
  box-shadow: 8px 8px 0 var(--ink);
}
.eyebrow, .footer {
  margin: 0;
  color: var(--green);
  font-size: .8rem;
  font-weight: 800;
  letter-spacing: .12em;
}
h1 { margin: 10px 0 8px; font-size: clamp(2rem, 8vw, 2.8rem); line-height: 1.1; }
.intro { margin: 0 0 28px; color: var(--muted); line-height: 1.5; }
.date-fields { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
label { display: grid; gap: 8px; font-weight: 700; }
input {
  width: 100%; min-height: 50px; padding: 10px;
  border: 2px solid #a9b9ad; border-radius: 9px;
  color: var(--ink); background: white; font: inherit;
}
input:hover { border-color: var(--green); }
input:focus-visible, button:focus-visible { outline: 3px solid var(--yellow); outline-offset: 3px; }
button {
  width: 100%; min-height: 54px; margin-top: 18px; padding: 12px 16px;
  border: 2px solid var(--ink); border-radius: 9px;
  color: white; background: var(--green); font: inherit; font-weight: 750;
  cursor: pointer; transition: transform .12s, background .12s;
}
button:hover { background: #1f503f; }
button:active { transform: translateY(2px); }
button span { margin-left: 6px; }
.results { margin-top: 28px; padding: 20px; border: 2px dashed #a9b9ad; border-radius: 12px; text-align: center; }
h2 { margin: 0 0 18px; font-size: 1.15rem; }
.stats { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.stat { display: grid; gap: 3px; padding: 14px 8px; border-radius: 9px; background: #e9f2ed; }
.stat strong { font-size: 2rem; line-height: 1.1; }
.stat span { color: var(--muted); }
#detail { margin: 16px 0 0; color: var(--muted); }
.footer { display: flex; justify-content: space-between; margin-top: 25px; font-size: .7rem; }
.footer span { color: #b17b18; font-size: 1rem; }
@media (max-width: 420px) {
  body { padding: 16px; }
  .date-fields { grid-template-columns: 1fr; gap: 14px; }
}

const form = document.getElementById('date-form');
const firstInput = document.getElementById('first-date');
const secondInput = document.getElementById('second-date');
const dayMs = 24 * 60 * 60 * 1000;

function utcDay(value) {
  const [year, month, day] = value.split('-').map(Number);
  return Date.UTC(year, month - 1, day) / dayMs;
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  if (!form.reportValidity()) return;

  const first = utcDay(firstInput.value);
  const second = utcDay(secondInput.value);
  const difference = Math.abs(second - first);
  const direction = second < first ? 'before' : second > first ? 'after' : 'the same day as';

  document.getElementById('direction').textContent = `The second date is ${direction} the first.`;
  document.getElementById('days').textContent = difference;
  document.getElementById('weeks').textContent = Math.floor(difference / 7);
  document.getElementById('detail').textContent = difference === 0
    ? 'These dates fall on the same day.'
    : `${difference % 7} day${difference % 7 === 1 ? '' : 's'} beyond the full weeks.`;
});
